#!/usr/bin/env python3
import base64
import gzip
import hashlib

_PAYLOAD = ''
_SOURCE = gzip.decompress(base64.b64decode(_PAYLOAD, validate=True))
_SOURCE_SHA256 = hashlib.sha256(_SOURCE).hexdigest()
if _SOURCE_SHA256 != 'd9aabedf4e4e499605324fa49eed8f7d830236152e46294c1fa31036a8c27a79':
    raise RuntimeError("A11_SOURCE_SHA256_MISMATCH")
exec(compile(_SOURCE.decode("utf-8"), __file__, "exec"), globals(), globals())
